import csv
import json
import os
import pathlib
import re
import sys
import zipfile
from collections import defaultdict
from typing import Dict, List, Tuple, Set

from lxml import etree

APPENDIX_SENTINEL = "이 부록 문단은 그대로 유지해야 합니다."
HP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"


def load_update_json(path: str) -> dict:
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def load_followups_csv(path: str) -> List[Tuple[int, str]]:
    rows: List[Tuple[int, str]] = []
    with open(path, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for r in reader:
            seq = int(r["sequence"])
            item = (r.get("item") or "").strip()
            rows.append((seq, item))
    rows.sort(key=lambda x: x[0])
    return rows


def collect_and_register_namespaces(tree: etree._ElementTree) -> Dict[str, str]:
    root = tree.getroot()
    nsmap = dict(root.nsmap) if root.nsmap else {}
    # Ensure hp prefix exists
    if "hp" not in nsmap:
        nsmap["hp"] = HP_NS
    # Register namespaces to avoid ns0/ns1 prefix churn
    for prefix, uri in nsmap.items():
        if prefix is None:
            # default namespace
            continue
        try:
            etree.register_namespace(prefix, uri)
        except ValueError:
            # Some prefixes might be invalid per lxml rules; ignore
            pass
    return nsmap


def iter_hp_text_runs(root: etree._Element, ns: Dict[str, str]):
    # text nodes are hp:t
    for t in root.xpath(".//hp:t", namespaces=ns):
        yield t


def paragraph_of_node(node: etree._Element) -> etree._Element:
    # walk up to nearest hp:p
    cur = node
    while cur is not None:
        if cur.tag == f"{{{HP_NS}}}p":
            return cur
        cur = cur.getparent()
    return None


def paragraph_text(p: etree._Element, ns: Dict[str, str]) -> str:
    ts = p.xpath(".//hp:t", namespaces=ns)
    return "".join((t.text or "") for t in ts)


def remove_linesegarray(p: etree._Element):
    # remove hp:lineSegArray (case-insensitive in sample is hp:linesegarray)
    # We'll remove any child element whose localname lower() == 'linesegarray'
    for child in list(p):
        if etree.QName(child).localname.lower() == "linesegarray":
            p.remove(child)


def build_old_values(root: etree._Element, ns: Dict[str, str]) -> Dict[str, str]:
    """Extract old values from the existing document by reading specific paragraphs/cells."""
    old = {}

    # Customer: paragraph that starts with "고객사:"
    for p in root.xpath(".//hp:p", namespaces=ns):
        txt = paragraph_text(p, ns)
        if txt.startswith("고객사:"):
            # after '고객사:' including possible space
            old["customer"] = txt.split(":", 1)[1].strip()
            break

    # Owner: paragraph that starts with "현 담당자:"
    for p in root.xpath(".//hp:p", namespaces=ns):
        txt = paragraph_text(p, ns)
        if txt.startswith("현 담당자:"):
            old["owner_name"] = txt.split(":", 1)[1].strip()
            break

    # Window: "갱신 윈도우:" or "갱신 윈도우 확인:"
    for p in root.xpath(".//hp:p", namespaces=ns):
        txt = paragraph_text(p, ns)
        if txt.startswith("갱신 윈도우:"):
            old["window"] = txt.split(":", 1)[1].strip()
            break

    # Band: find cell where text equals "가격 밴드" then take sibling cell text
    # Simplest: find first paragraph with exact text Standard-18M? But we want robust.
    tbl_ps = root.xpath(".//hp:tbl//hp:p", namespaces=ns)
    for i, p in enumerate(tbl_ps):
        if paragraph_text(p, ns).strip() == "가격 밴드":
            # next paragraph in table likely is value
            # seek forward to first non-empty that isn't label and is in adjacent cell
            for j in range(i + 1, min(i + 6, len(tbl_ps))):
                cand = paragraph_text(tbl_ps[j], ns).strip()
                if cand and cand != "가격 밴드" and cand != "에스컬레이션 연락처":
                    old["band"] = cand
                    break
            break

    # Escalation email: find label then next value
    for i, p in enumerate(tbl_ps):
