def make_replacement_map(old_vals: Dict[str, str], new_vals: dict) -> Dict[str, str]:
    repl = {}
    # customer: allow old may include multiple runs already combined; we will replace exact substring
    if old_vals.get("customer"):
        repl[old_vals["customer"]] = new_vals["customer"]
    if old_vals.get("owner_name"):
        repl[old_vals["owner_name"]] = new_vals["owner_name"]
    if old_vals.get("window"):
        new_window = f"{new_vals['window_start']} ~ {new_vals['window_end']}"
        repl[old_vals["window"]] = new_window
    if old_vals.get("band"):
        repl[old_vals["band"]] = new_vals["band"]
    if old_vals.get("escalation_email"):
        repl[old_vals["escalation_email"]] = new_vals["escalation_email"]
    if old_vals.get("note"):
        repl[old_vals["note"]] = new_vals["note"]
    return repl


def replace_text_runs(tree: etree._ElementTree, repl_map: Dict[str, str]) -> Set[etree._Element]:
    """Replace within hp:t runs. Returns paragraphs that had modifications."""
    root = tree.getroot()
    ns = collect_and_register_namespaces(tree)
    modified_paras: Set[etree._Element] = set()

    for t in iter_hp_text_runs(root, ns):
        if t.text is None:
            continue
        if APPENDIX_SENTINEL in t.text:
            # Do not touch the appendix sentence run.
            continue
        old_text = t.text
        new_text = old_text
        for old, new in repl_map.items():
            if old and old in new_text:
                new_text = new_text.replace(old, new)
        if new_text != old_text:
            t.text = new_text
            p = paragraph_of_node(t)
            if p is not None:
                modified_paras.add(p)

    return modified_paras


def locate_followup_paragraphs(tree: etree._ElementTree) -> List[etree._Element]:
    root = tree.getroot()
    ns = collect_and_register_namespaces(tree)

    followups = []
    for p in root.xpath(".//hp:p", namespaces=ns):
        txt = paragraph_text(p, ns).strip()
        if re.match(r"^[1-9]\d*\.\s+", txt) and "old follow-up" in txt:
            followups.append(p)
    return followups


def replace_followups(tree: etree._ElementTree, new_items: List[Tuple[int, str]]) -> Set[etree._Element]:
    """Replace the three existing follow-up lines with new items. Reuse style/structure."""
    root = tree.getroot()
    ns = collect_and_register_namespaces(tree)

    old_ps = locate_followup_paragraphs(tree)
    if not old_ps:
        raise RuntimeError("Could not locate existing follow-up paragraphs")

    # Use first old paragraph as template (deep copy)
    template_p = old_ps[0]
    parent = template_p.getparent()
    if parent is None:
        raise RuntimeError("Template follow-up paragraph has no parent")

    # Find insertion index (position of first old paragraph among parent's children)
    siblings = list(parent)
    first_idx = siblings.index(template_p)

    # Remove old follow-up paragraphs
    for p in old_ps:
        parent.remove(p)

    # Insert new paragraphs in order
    inserted: List[etree._Element] = []
    for idx, (_seq, item) in enumerate(new_items, start=1):
        p_new = etree.fromstring(etree.tostring(template_p))  # clone
        # Update all hp:t text inside to "{idx}. {item}" (keep structure; if multiple runs, set first and clear rest)
        ts = p_new.xpath(".//hp:t", namespaces=ns)
        desired = f"{idx}. {item}"
        if not ts:
            # If unexpected, create a run/t
            run = etree.SubElement(p_new, f"{{{HP_NS}}}run")
            t = etree.SubElement(run, f"{{{HP_NS}}}t")
            t.text = desired
        else:
            ts[0].text = desired
            for extra in ts[1:]:
                extra.text = ""
        inserted.append(p_new)

    for offset, p_new in enumerate(inserted):
        parent.insert(first_idx + offset, p_new)

    return set(inserted)


def remove_linesegarray_for_modified_paras(paras: Set[etree._Element]):
    for p in paras:
        # Do not touch appendix paragraph at all
        # Check exact paragraph text
        # (paragraph may contain only that sentence)
        # If it matches, skip
        try:
            # local quick check by concatenating all text nodes
            txt = "".join((t.text or "") for t in p.xpath(".//hp:t", namespaces={"hp": HP_NS}))
        except Exception:
            txt = ""
        if txt.strip() == APPENDIX_SENTINEL:
            continue
        remove_linesegarray(p)


def parse_xml(path: pathlib.Path) -> etree._ElementTree:
    parser = etree.XMLParser(remove_blank_text=False)
    tree = etree.parse(str(path), parser)
    collect_and_register_namespaces(tree)
    return tree


def write_xml(tree: etree._ElementTree, path: pathlib.Path):
    data = etree.tostring(
        tree,
        encoding="UTF-8",
        xml_declaration=True,
        pretty_print=False,
    )
    path.write_bytes(data)


def zip_dir_to_hwpx(src_dir: pathlib.Path, out_hwpx: pathlib.Path):
    if out_hwpx.exists():
        out_hwpx.unlink()
    with zipfile.ZipFile(out_hwpx, "w", compression=zipfile.ZIP_DEFLATED) as z:
        for path in sorted(src_dir.rglob("*")):
            if path.is_file():
